#!/usr/bin/env python3
"""Assemble generate_v6.js from generate_v5.js: v5 sections 1-4.4 are kept verbatim (frozen history); G2 sections,
title, abstract, discussion, limitations, reproducibility and references are new. Every G2 number is read from
numbers_v6.json at generation time (template literals), never typed here."""
import io

v5 = io.open("generate_v5.js", encoding="utf8").read().split("\n")
L = lambda a, b: "\n".join(v5[a - 1:b])          # 1-based inclusive line range of v5

HEAD = '''/* Generate manuscript v6 (v5.2 + G2 causal-specificity, failure-locus and repair results). All G2 numbers come from
   numbers_v6.json, produced by extract_numbers_v6.py from the archived analysis JSONs and receipts. */'''
NUMS = '''const N = require("./numbers_v6.json");
const A = N.A, B = N.B, C = N.C, D = N.D, E = N.E;
const s = x => (x === 0 || Object.is(x, -0) ? "0.00" : (x > 0 ? "+" : "") + x.toFixed(2));
const pct = x => x.toFixed(1);
const E11a = E.summary.L11_action, E11all = E.summary.L11_all, E12all = E.summary.L12_all;
const D11 = D.layers["11"], D12 = D.layers["12"];
const TOTAL_FWD = N.ledger_total_g2 + N.ledger_prior_line;
const RB = N.robust, TOPG = RB.top_donor_group.replace("twins_streamlet:", "");
'''

TITLE = '''  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 120, line: 312 }, children: [new TextRun({ text: "Missed When Added, Repaired When Implanted: Specific Cross-Group Causal Evidence for an Encoding Failure of Appended Conflicts in a Security-Typed Language-Model Scorer", bold: true, size: 30, font: FONT })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 60, line: 312 }, children: [new TextRun({ text: "Anonymous draft (v6; the v5.2 audit extended with five preregistered G2 causal stages)", size: BODY, font: FONT })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 240, line: 312 }, children: [new TextRun({ text: `Complete evidence chain (designs, manifests and analysis scripts frozen on CPU before every GPU stage; ${TOTAL_FWD.toLocaleString("en-US")} native FP32 forward passes across ten GPU stages with archived raw logits, durable quota ledgers, bitwise cross-stage replays, formal errata and SHA-pinned readbacks) archived in repository dddd2024/jev`, size: 19, italics: true, font: FONT, color: "444444" })] }),'''

ABSTRACT = '''  h("Abstract", HeadingLevel.HEADING_1),
  p(`When new policy-relevant evidence arrives in a security decision context, does a trained scorer encode it - and if it does not, can the failure be repaired from the inside? We study SecJev-0.8B, a security-typed 0.8B scorer with independent typed question rows over structured consensus scenes with executable rule oracles. Appending one valid equivocation vote - an edit that lawfully moves the gold to rejection - is missed in ${pct(A.missed_rate_new)}% of ${A.scenes} tier-2 scenes screened in a preregistered GPU stage (strict recognition in ${A.strict}, and in ${D.D1["31"].strict + D.D1["34"].strict} of ${D.D1["31"].scenes + D.D1["34"].scenes} further scenes), extending earlier counts of 1/20 and 1/36. Earlier rounds localized the failure to the candidate-key side of the conflict head's pointer readout, and a one-donor pilot showed mid-depth span sensitivity. Here we test that account with five preregistered, CPU-frozen GPU stages (${N.ledger_total_g2.toLocaleString("en-US")} native forwards) built on the ${A.strict} recognized donors (${A.groups.length} source groups) and hosts from other groups. (i) Specificity: transplanting a recognized donor's appended-span representation at layer 11 into a host's neutral span raises the conflict margin by a median ${s(C.H1.median_dM.main)} logits and exceeds the donor's own duplicate-vote span, a position-permuted copy and a dose-matched random perturbation of identical per-position size in ${C.H1.supportive}/${C.H1.cells} donor x host cells (dose-matched median ${s(C.H1.median_dM.dose1)}); a whole-span norm-matched control approaches the main effect only because it is a far larger perturbation. (ii) Window: the span dependence is strong at layer 11, weaker at layer 12 and absent by layer ${C.H2_boundary} in both directions. (iii) Locus: replacing a donor's recognized span with a host's missed-conflict span suppresses recognition as much as the host's non-conflict duplicate span (the main arm is stronger in only ${C.H1b.main_beats_sasham}/16 cells), while dose-matched noise barely moves it; a preregistered projection test separates missed from recognized scenes with AUC ${C.H3.auc_L11.toFixed(2)} at layer 11 (short of its 0.9 threshold; ${C.H3.auc_L12.toFixed(2)} at layer 12). (iv) Repair: in ${D.n_hosts} near-threshold hosts from ${D.n_host_groups} further groups, implanting a recognized span into the host's own missed-conflict span flips the conflict readout in ${D11.specific_flip}/${D11.cells} cells with neither control flipping, across all ${D11.host_groups} host groups; implanting it into the certificate-action row alone flips the decision to reject_conflict in ${E11a.specific_reject}/${E11a.cells} cells (controls: ${E11a.rejects.sasham} and ${E11a.rejects.doserand} rejections) across all ${E11a.donor_groups} donor groups and ${E11a.host_groups} of ${D.n_host_groups} host groups, with every other question row bitwise unchanged. We read this as specific, cross-group causal evidence that the scorer's failure on appended conflicts is an encoding failure at the appended span by mid-depth that is repairable by implanting a recognized encoding, and we state its ceilings: one donor (${TOPG}) contributes ${RB.top_donor_E_rejects} of the ${E11a.specific_reject} decision repairs (without it, ${RB.E_without_top.specific}/${RB.E_without_top.cells} cells across two donor and two host groups remain); four donors from three previously used source groups; one model; one simulator family; constructed edits; non-independent cells; one missed preregistered threshold; and one documented design erratum.`),'''

INTRO_ADD = '''  p(`This version adds the causal program that the v5 pilot could only motivate. Five GPU stages, each designed, manifested and given a frozen analysis script before any forward pass, make four contributions. First, a preregistered screen of all remaining constructible candidates bounds the rarity of recognition (${A.strict} strict donors in ${N.screened_total} scenes). Second, crossed donor x host transplants with SA-sham, permuted and dose-matched random controls show that the recognized span carries content-specific information at layer 11 across source groups. Third, layer profiles, suppression controls and a capture-based projection test locate the failure at the encoding of the appended span, not in either readout. Fourth, implanting a recognized encoding repairs both the conflict readout and, when placed in the decision row itself, the certificate action - the behavioral endpoint the scorer exists to produce.`),'''

RELATED_ADD = '''  p(`Three recent lines bear directly on the G2 results. Lepori, Mozer and Ghandeharioun (2024) attribute contextualization errors to timing: a dependent token reads an entity representation before it is formed. Lepori et al. (2026) find the opposite dissociation in in-context learning: novel semantics are encoded in hidden states but not deployed. Abdelsalam et al. (2026) use residual-stream activation patching to locate where misleading code comments override execution semantics. Our evidence points to a third case: the appended conflict is not encoded as a conflict at the span by mid-depth (its transplant behaves like a duplicate vote), while a recognized encoding, once present, is used by two independent readers - the conflict row and the action row. Methodologically, activation patching can create illusory localization through dormant or off-manifold pathways (Makelov, Lange and Nanda, 2023), and its conclusions depend on corruption and metric choices (Zhang and Nanda, 2024). We therefore transplant whole residual span states taken from natural forward passes of real scenes rather than subspace directions, and compare every main arm with an in-distribution sham (the same model's span for a duplicate vote at the same position), a permutation, and a random direction matched to the main arm's per-position perturbation size. To our knowledge, no prior work tests evidence-integration failures in a security-typed scorer with cross-group transplants under dose-matched controls, or repairs the decision by patching the decision row's own copy of the evidence span while verifying bitwise that the other rows are untouched.`),'''

METHOD_ADD = '''  h("3.4  G2 causal stages: screening, specificity, locus and repair", HeadingLevel.HEADING_2),
  p(`G2 starts from a CPU-frozen roster of 172 tier-2 candidates (source groups not used by the pilot), each with a full-request token gate and a frozen-width witness: the appended vote (new arm) or a same-author duplicate vote (SA arm) occupies an exact span of W tokens after the first token divergence from the old arm, with the trailing state verified token-identical. Stage A screens 124 W = 31 candidates (old, new and SA arms; ${A.physical} forwards) and qualifies donors by the strict rule C(old) = false, C(new) = true, C(SA) = false, where C is the conflicting_vote readout and M = z_true - z_false its margin. Stage B crosses the ${A.strict} donors with 4 hosts from 4 other groups (all arms false) at the outputs of the full-attention layers 7, 11 and 15 (layer 11 confirmatory; layer 23 excluded as a structural null), patching the host SA span (restoration) or the donor new span (suppression) with a main arm and SA-sham, permuted and norm-matched random controls (${B.physical} forwards). Stage C captures the conflict-row span at all 24 layer outputs for the 124 screened scenes (new and SA arms) and repeats the crossed design at layers 11-14 with a dose-matched random control: target_i + u_i ||source_i - target_i|| per position i, u_i a seeded unit Gaussian direction (${C.physical} forwards). Stage D screens the 47 remaining roster scenes and patches the donors' recognized spans into the own missed-conflict span of ${D.n_hosts} near-threshold hosts (Stage-A pattern FFF, M_new >= -4.0, outside donor groups) at layers 11-12 (${D.physical} forwards). Stage E repeats the repair with per-row patching: because each question is an independent causal row in the hybrid backbone's row form, captures store every row's copy of the span and patches overwrite the certificate-action row only, or every row, each with the same row's source span; the action margin is A = z_reject_conflict - max(z_accept, z_wait) (${E.physical} forwards).`),
  p(`Every stage's design, one-row-per-call manifest and analysis script were committed before its GPU run, with decision rules stated as counts (Sections 4.5-4.9). Each run required the user's explicit approval of that exact runner version and budget, recorded verbatim in an admission file; a durable per-approval quota ledger reserved every call before the model ran, an LM pre-hook refused any unreserved, over-cap or over-budget call, each batch held at most 128 calls, and pinned hashes covered the model weights, tokenizer and source. Baselines were not re-estimated: every capture forward had to equal its earlier-stage logits bitwise (Stage C also replicated 64 Stage-B patch rows bitwise), so all deltas are measured against archived values. Statistical units are source groups (${A.groups.length} donor groups; ${N.host_groups_union} distinct host groups across Stages B-E); cells share donors and hosts and are not independent, so all counts are descriptive decision rules rather than p-values.`),'''

RESULTS_ADD = '''  h("4.5  G2 screen: appended conflicts are missed in most scenes", HeadingLevel.HEADING_2),
  p(`Across the 124 Stage-A scenes, the conflict readout is true for ${pct(100 * A.C_rate.old)}% of old arms, ${pct(100 * A.C_rate.new)}% of new arms and ${pct(100 * A.C_rate.SA)}% of SA arms, and the median margin moves by only ${s(A.median_dM_new_old)} logits when the conflict is appended. Strict recognition occurs in ${A.strict} scenes (${A.groups.map(g => g.replace("twins_streamlet:", "")).join(", ")}); the remaining patterns are ${Object.entries(A.patterns).map(([k, v]) => k + " " + v).join(", ")} (old/new/SA). In all four donors the certificate action also follows the recognized conflict (reject_conflict on the new arm only). The Stage-D screen of the remaining roster adds none (W = 31: ${Object.entries(D.D1["31"].patterns).map(([k, v]) => k + " " + v).join(", ")}; W = 34: ${Object.entries(D.D1["34"].patterns).map(([k, v]) => k + " " + v).join(", ")}), so the donor pool is exhausted at ${A.strict} donors from ${A.groups.length} groups.`),

  h("4.6  Specificity: the recognized span carries content beyond dose, position and token form", HeadingLevel.HEADING_2),
  caption("Table 3. Restoration at layer 11 (donor recognized span -> host neutral SA span; 4 donors x 4 hosts). dM = change in the host conflict margin; cells won = cells in which the main arm exceeds that control."),
  table(
    ["Control (stage)", "Median dM main", "Median dM control", "Cells won by main", "Flips main / control"],
    [
      ["SA-sham: donor duplicate-vote span (B)", s(B.summary.restoration_L11.median_dM.main), s(B.summary.restoration_L11.median_dM.sasham), `${B.rest_L11_beats.sasham}/16`, `${B.summary.restoration_L11.flips.main} / ${B.summary.restoration_L11.flips.sasham}`],
      ["Position-permuted donor span (B)", s(B.summary.restoration_L11.median_dM.main), s(B.summary.restoration_L11.median_dM.permuted), `${B.rest_L11_beats.permuted}/16`, `${B.summary.restoration_L11.flips.main} / ${B.summary.restoration_L11.flips.permuted}`],
      ["Whole-span norm-matched random (B)", s(B.summary.restoration_L11.median_dM.main), s(B.summary.restoration_L11.median_dM.normrand), `${B.rest_L11_beats.normrand}/16`, `${B.summary.restoration_L11.flips.main} / ${B.summary.restoration_L11.flips.normrand}`],
      ["Dose-matched random, 2 seeds (C)", s(C.H1.median_dM.main), s(C.H1.median_dM.dose1), `${C.H1.supportive}/${C.H1.cells} (both seeds)`, `${C.restoration_L11_flips.main} / ${C.restoration_L11_flips.dose1 + C.restoration_L11_flips.dose2}`],
    ],
    [34, 15, 17, 18, 16]
  ),
  note(`Stage B's preregistered verdict was ${B.verdict}: restoration met its rule (${B.summary.restoration_L11.supportive}/16 cells supportive over all three controls, all donor and host groups) while suppression did not (Section 4.8). The whole-span norm-matched control replaces the span with noise (main-patch span cosine to the host span: median ${B.span_cos_L11_median}), a much larger perturbation than the main arm; Stage C's dose-matched control equalizes per-position perturbation size and leaves the main arm ahead in every cell (median gap ${s(C.H1.median_gap)}), meeting the preregistered content-specificity rule (>= 10/16 cells, all donor groups, positive median gap). Hosts sit near M = -11, so no restoration flips the read; flips are tested in Section 4.9.`),

  h("4.7  Window: the readout stops depending on the span between layers 12 and 13", HeadingLevel.HEADING_2),
  p(`Median main-arm effects at layers 11, 12, 13 and 14 are ${["11", "12", "13", "14"].map(l => s(C.H2.restoration[l])).join(", ")} logits for restoration and ${["11", "12", "13", "14"].map(l => s(C.H2.suppression[l])).join(", ")} for suppression; the preregistered boundary (first layer below 10% of the layer-11 effect in both directions) is layer ${C.H2_boundary}. In Stage B, layer 15 effects were near zero in both directions, and at layer 7 restoration did not exceed whole-span noise (median ${s(B.summary.restoration_L7.median_dM.main)} vs ${s(B.summary.restoration_L7.median_dM.normrand)}) while suppression flipped the donor read under the main, SA-sham and permuted arms in every cell and under whole-span noise in ${B.summary.suppression_L7.flips.normrand}/16 cells. Within this backbone, then, the appended span is read out in a narrow mid-depth window: at layer 7 any large perturbation disrupts, and by layer 13 the readout no longer consults the span positions.`),

  h("4.8  Locus: a missed conflict is encoded like a duplicate vote", HeadingLevel.HEADING_2),
  p(`Replacing a donor's recognized span with a host's missed-conflict span at layer 11 lowers the donor margin by a median ${s(C.H1b.median_dM.main)}, but replacing it with the same host's duplicate-vote span lowers it by ${s(C.H1b.median_dM.sasham)}; the main arm is the stronger in only ${C.H1b.main_beats_sasham}/16 cells (Stage B: ${B.supp_L11_beats.sasham}/16), so suppression is not specific to conflict content - the preregistered Stage-B suppression rule failed. Dose-matched noise moves the donor margin by only ${s(C.H1b.median_dM.dose1)} (main arm stronger in ${C.H1b.supportive}/16 cells), so the donor's recognition depends on its own span content rather than on perturbation size. Read together, the host's span for an appended conflict acts like its span for a harmless duplicate vote. A preregistered capture test probes the same point directly: projecting each scene's new-minus-SA span difference onto a leave-one-donor-out conflict direction, missed scenes (FFF) have a median score of ${C.H3.median_p_FFF_L11.toFixed(2)} at layer 11, below every held-out donor (${C.H3.donor_p_L11.map(x => x.toFixed(2)).join(", ")}). The recognized-vs-missed AUC is ${C.H3.auc_L11.toFixed(2)} at layer 11, short of the preregistered 0.9, so the layer-11 prediction is reported as not met; across layers the AUC peaks at ${C.H3.auc_peak.toFixed(2)} (layer ${C.H3.auc_peak_layer}). With only four donors defining the direction, this test is low-powered, and we treat it as consistent with, not as proof of, the encoding account.`),

  h("4.9  Repair: implanting a recognized encoding flips the readout and the decision", HeadingLevel.HEADING_2),
  caption("Table 4. Repair in near-threshold hosts (donor recognized span -> host's own missed-conflict span; 4 donors x 8 hosts per setting). Specific = main arm flips and neither SA-sham nor dose-matched random does."),
  table(
    ["Stage, layer, rows patched", "Endpoint", "Flips: main / SA-sham / dose", "Specific flips", "Donor groups", "Host groups"],
    [
      ["D, L11, conflict row", "C read true", `${D11.flips.main} / ${D11.flips.sasham} / ${D11.flips.dose}`, `${D11.specific_flip}/${D11.cells}`, `${D11.donor_groups}/3`, `${D11.host_groups}/${D.n_host_groups}`],
      ["D, L12, conflict row", "C read true", `${D12.flips.main} / ${D12.flips.sasham} / ${D12.flips.dose}`, `${D12.specific_flip}/${D12.cells}`, `${D12.donor_groups}/3`, `${D12.host_groups}/${D.n_host_groups}`],
      ["E, L11, action row only", "reject_conflict", `${E11a.rejects.main} / ${E11a.rejects.sasham} / ${E11a.rejects.doserand}`, `${E11a.specific_reject}/${E11a.cells}`, `${E11a.donor_groups}/3`, `${E11a.host_groups}/${D.n_host_groups}`],
      ["E, L11, all rows", "reject_conflict", `${E11all.rejects.main} / ${E11all.rejects.sasham} / ${E11all.rejects.doserand}`, `${E11all.specific_reject}/${E11all.cells}`, `${E11all.donor_groups}/3`, `${E11all.host_groups}/${D.n_host_groups}`],
      ["E, L12, all rows", "reject_conflict", `${E12all.rejects.main} / ${E12all.rejects.sasham} / ${E12all.rejects.doserand}`, `${E12all.specific_reject}/${E12all.cells}`, `${E12all.donor_groups}/3`, `${E12all.host_groups}/${D.n_host_groups}`],
    ],
    [24, 14, 20, 14, 13, 15]
  ),
  note(`Hosts: Stage-A FFF scenes with M_new from ${D.hosts_M_new_range[0]} to ${D.hosts_M_new_range[1]} and action margin A_new from ${E.host_A_range[0]} to ${E.host_A_range[1]} (none rejecting at baseline). Median dM at D/L11: main ${s(D11.median_dM.main)}, SA-sham ${s(D11.median_dM.sasham)}, dose ${s(D11.median_dM.dose)}; median dA at E/L11 (action row): main ${s(E11a.median_dA.main)}, SA-sham ${s(E11a.median_dA.sasham)}, dose ${s(E11a.median_dA.doserand)}. Integrity: with only the action row patched, the conflict, evidence-level and quorum rows equal the baseline bitwise in every row (${E.reachability_violations} violations); main and SA-sham action logits are bitwise identical between the action-row and all-row scopes; the span is bitwise identical across question rows (max difference ${E.cross_row_max}); the all-row setting reproduces Stage D's ${E11all.c_flips_main} layer-11 conflict flips.`),
  p(`The preregistered Stage-D verdict was NO_BEHAVIOURAL_CORRECTION, and we report it with an erratum: Stage B-D patches overwrote the span only in the conflict row, so the certificate-action row - an independent causal row with its own copy of the state - could not change, and the preregistered action criterion was unattainable by construction (verified: all non-conflict logits bitwise equal to baseline in all 192 Stage-D patch rows). Stage E corrected the design and met its preregistered rule (ACTION_LEVEL_CORRECTION: specific rejections spanning >= 2 donor and >= 2 host groups). ${E.hosts_with_specific_reject_L11_action} of ${D.n_hosts} hosts reached at least one specific rejection, including the host furthest from the threshold (A = ${E.host_A_range[0]}). The decision flips with the conflict row untouched: the action row reads the appended span through its own copy, and implanting a recognized encoding there is sufficient to produce the rule-mandated decision. Repair is confined to layer 11: no rejection occurs at layer 12, consistent with the window in Section 4.7. Repairs are unevenly distributed across donors (${TOPG}: ${RB.top_donor_E_rejects} of ${E11a.specific_reject}); Section 5 reports an exploratory leave-one-donor-out check.`),'''

DISCUSSION = '''  h("5  Discussion", HeadingLevel.HEADING_1),
  p(`The v5 account - a key-side localization plus a one-donor signed sensitivity - left open whether the appended-span representation carries conflict information specifically, where the failure lies, and whether it matters for the decision. G2 answers all three within its ceilings. The recognized span carries content-specific information: across three donor groups and four host groups it outperforms its own duplicate-vote span, its permutation, and a random perturbation of exactly its size. The failure lies upstream of both readouts: a missed conflict's span, substituted for a recognized one, suppresses recognition about as strongly as a duplicate vote does, and missed scenes project weakly onto the conflict direction. And it matters for the decision: implanting a recognized encoding into the action row's own copy of the span produces the rule-mandated rejection without touching the conflict row. The coherent reading is an encoding failure: by mid-depth the scorer has not represented an appended equivocation as a conflict, and two independent readers (the conflict head and the action head) both act on whatever the span encodes. This differs from a timing account (the readout consults the span at layers 11-12, and a recognized encoding placed there is used) and from an encode-but-don't-use account (the missed span is not encoded as a conflict to begin with).`),
  p(`The effects are causal under natural-activation transplants, not under arbitrary vectors, and the controls bound the alternatives we can name: token form and position (SA-sham, permutation), perturbation size (dose-matched random, two seeds), and off-manifold disruption (whole-span noise, which approaches the main effect at layer 11 and disrupts indiscriminately at layer 7 - a caution that norm-matching alone is an inadequate control in this backbone). Effect sizes are moderate: restoration moves a deep-negative host by about two logits, and repair flips 10 of 32 cells. Which cells flip is not explained by host distance from the threshold (median baseline A ${RB.median_A_flipped.toFixed(2)} for repaired vs ${RB.median_A_not_flipped.toFixed(2)} for unrepaired cells), but it is concentrated by donor: the ${TOPG} donor accounts for ${RB.top_donor_E_rejects} of ${E11a.specific_reject} decision repairs and ${RB.top_donor_D_flips} of ${D11.specific_flip} readout repairs. An exploratory leave-one-donor-out check (not preregistered) keeps the preregistered cross-group rule for decision repair whichever donor is removed, but without ${TOPG} only ${RB.E_without_top.specific}/${RB.E_without_top.cells} cells remain, spanning two donor and two host groups (readout repair: ${RB.D_without_top.specific}/${RB.D_without_top.cells}); dose specificity, in contrast, holds in at least ${RB.C_lodo_min}/12 cells for every removal. The claim is therefore that an implanted recognized encoding is sufficient to repair the decision in a cross-group subset of near-threshold scenes, with sufficiency varying strongly between donors - not that every recognized encoding repairs every scene.`),
''' + L(136, 136) + '''
  p(`G2 continued that pattern. Three independent engineering reviews rejected successive versions of our GPU runner before any G2 forward pass (a replay that could not run, an overridable input plan, an advisory rather than durable quota, and a per-batch cap not enforced at the LM hook itself); fixing them produced the quota ledger and pre-hook gate that every later stage reused. During G2, a self-test caught raw rows missing their scope labels, and a post-run check exposed our own design error in Stage D's action criterion. That criterion is reported as an erratum next to its verdict, and the corrected Stage E was frozen before it ran. Bitwise cross-stage replays (every capture equal to Stage A; Stage C equal to Stage B on 64 patch rows) make each stage's deltas relative to the same archived baselines.`),
  p(`Boundaries. The causal statements are about one 0.8B checkpoint, one simulator family and synthetic but rule-valid edits. Donors are rare (4 strict in 171 scenes) and come from three source groups that earlier rounds had already used for other scenes, and the roster is exhausted, so donor diversity cannot be increased without new construction. Cells share donors and hosts, so counts are descriptive. The locus test missed its preregistered threshold at layer 11. We make no deployment, attacker-reachability or cross-model claim, and the deterministic-rule ceiling stands: a parsed policy engine solves this task exactly, so the contribution is a mechanistic account of how a trained scorer fails and how that failure can be causally repaired, not an argument for model-based decisions.`),'''

LIMITS = '''  h("6  Limitations", HeadingLevel.HEADING_1),
  p(`One 0.8B checkpoint and one simulator family; constructed rather than observed edits. Four strict donors from three source groups, all previously used by earlier rounds for other scenes (no never-used groups exist), and an exhausted candidate roster; hosts come from ${N.host_groups_union} further groups. Repair effects are concentrated in one donor (${TOPG}: ${RB.top_donor_E_rejects}/${E11a.specific_reject} decision and ${RB.top_donor_D_flips}/${D11.specific_flip} readout repairs); without it the cross-group repair rule is met only at its minimum (two donor and two host groups). Every main effect is a count over cells that share donors and hosts, with source groups as the statistical unit, and no significance test is claimed. The capture-based locus test missed its preregistered layer-11 threshold (AUC ${C.H3.auc_L11.toFixed(2)} < 0.9), and its conflict direction is estimated from four donors. Restoration never flips deep-negative hosts; repair flips about a third of near-threshold cells at layer 11 and none at layer 12. Layers outside 7 and 11-15 are untested by patching. Stage D's preregistered action criterion was structurally unattainable (erratum). The SA-sham, permutation and random controls exclude token-form, position and dose explanations, but not every off-manifold interaction a full-state transplant can create; we do not claim a Key-only or any component-level mediation. Cross-model replication, observed (non-constructed) evidence streams and deployment relevance remain open.`),'''

